begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('d0000000-0000-4000-8000-000000000001','bank-owner@example.test',now()),
 ('d0000000-0000-4000-8000-000000000002','bank-seller@example.test',now()),
 ('d0000000-0000-4000-8000-000000000003','bank-staff@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"d0000000-0000-4000-8000-000000000001","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Synthetic bank store','synthetic-bank-store',gen_random_uuid())::text,true);
select set_config('test.seller',register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Synthetic seller','bank-seller@example.test','')::text,true);
select set_config('test.account',gen_random_uuid()::text,true);
select set_config('test.details','{"holder":"Synthetic seller","country":"SE","kind":"local","account":"123456789","routing":"1234"}',true);
select throws_ok($$select save_seller_bank_details(current_setting('test.tenant')::uuid,current_setting('test.account')::uuid,current_setting('test.seller')::uuid,null,current_setting('test.details')::jsonb)$$,'42501',null,'owner cannot edit on behalf of seller');
set local "request.jwt.claims"='{"sub":"d0000000-0000-4000-8000-000000000002","role":"authenticated"}';
select lives_ok($$select save_seller_bank_details(current_setting('test.tenant')::uuid,current_setting('test.account')::uuid,current_setting('test.seller')::uuid,null,current_setting('test.details')::jsonb)$$,'seller saves own account');
select lives_ok($$select save_seller_bank_details(current_setting('test.tenant')::uuid,current_setting('test.account')::uuid,current_setting('test.seller')::uuid,null,current_setting('test.details')::jsonb)$$,'save retry is exact');
select is(seller_bank_details(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)->>'id',current_setting('test.account'),'seller reads own account');
select throws_ok($$select save_seller_bank_details(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,null,current_setting('test.details')::jsonb)$$,'P0001','BANK_DETAILS_CHANGED','stale edit refused');
select is((select count(*)::int from seller_bank_versions),0,'seller has no raw table access');
reset role;
insert into tenant_members(tenant_id,user_id,role) values(current_setting('test.tenant')::uuid,'d0000000-0000-4000-8000-000000000003','staff');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"d0000000-0000-4000-8000-000000000003","role":"authenticated"}';
select throws_ok($$select seller_bank_details(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)$$,'42501',null,'staff cannot read bank details');
select is((select count(*)::int from seller_bank_versions),0,'RLS hides details from staff');
set local "request.jwt.claims"='{"sub":"d0000000-0000-4000-8000-000000000001","role":"authenticated"}';
select adjust_seller_ledger(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,20000,'Synthetic credit');
select set_config('test.payout',request_payout(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,10000)::text,true);
select throws_ok($$select approve_payout(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.payout')::uuid,'')$$,'P0001','PAYOUT_BANK_REVIEW_REQUIRED','approval requires explicit account review');
select review_payout_bank_details(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.payout')::uuid,current_setting('test.account')::uuid);
select approve_payout(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.payout')::uuid,'');
select is(payout_bank_details(current_setting('test.tenant')::uuid,current_setting('test.payout')::uuid)->'reviewed'->>'id',current_setting('test.account'),'approval freezes account version');
set local "request.jwt.claims"='{"sub":"d0000000-0000-4000-8000-000000000002","role":"authenticated"}';
select set_config('test.next',gen_random_uuid()::text,true);
select save_seller_bank_details(current_setting('test.tenant')::uuid,current_setting('test.next')::uuid,current_setting('test.seller')::uuid,current_setting('test.account')::uuid,current_setting('test.details')::jsonb||'{"account":"987654321"}');
set local "request.jwt.claims"='{"sub":"d0000000-0000-4000-8000-000000000001","role":"authenticated"}';
select throws_ok($$select mark_payout_paid(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.payout')::uuid,'test-bank-transfer','')$$,'P0001','PAYOUT_BANK_REVIEW_REQUIRED','changed account prevents payment recording');
select review_payout_bank_details(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.payout')::uuid,current_setting('test.next')::uuid);
select lives_ok($$select mark_payout_paid(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.payout')::uuid,'test-bank-transfer','')$$,'payment follows new account review');
select is((select count(*)::int from payout_bank_reviews where payout_id=current_setting('test.payout')::uuid),2,'previous reviewed account retained');
set local "request.jwt.claims"='{"sub":"d0000000-0000-4000-8000-000000000002","role":"authenticated"}';
select throws_ok($$select save_seller_bank_details(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,current_setting('test.next')::uuid,current_setting('test.details')::jsonb||'{"kind":"iban","account":"SE4550000000058398257467"}')$$,'P0001','INVALID_INPUT','invalid IBAN checksum rejected in engine');
select save_seller_bank_details(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,current_setting('test.next')::uuid,current_setting('test.details')::jsonb||'{"account":"112233445"}');
set local "request.jwt.claims"='{"sub":"d0000000-0000-4000-8000-000000000001","role":"authenticated"}';
select adjust_seller_ledger(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,-10000,'Synthetic correction');
select is((seller_privacy_preview(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)->'counts'->>'bankRemovable')::int,1,'privacy preview identifies unused account version');
select is((seller_privacy_preview(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)->'counts'->>'bankRetained')::int,2,'privacy preview identifies payout evidence');
select erase_seller_contact(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,seller_privacy_preview(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)->>'revision','Retain reviewed payout evidence',current_date+30,true);
select is((select count(*)::int from seller_bank_versions where seller_id=current_setting('test.seller')::uuid),2,'erasure removes unused versions while preserving payment evidence');
select throws_ok($$update seller_bank_versions set details='{}' where id=current_setting('test.account')::uuid$$,'42501',null,'direct account mutation is denied');
reset role;
select ok(not has_function_privilege('anon','public.save_seller_bank_details(uuid,uuid,uuid,uuid,jsonb)','execute'),'anonymous bank write denied');
select ok(not has_function_privilege('anon','public.seller_bank_details(uuid,uuid)','execute'),'anonymous bank read denied');
select * from finish();
rollback;
